import {categoryArtMarkup} from './category-art.js';
import {createCategoryDraw} from './category-draw.js';
import {CATEGORIES,makePools,poolSize,customCards,drawRound,proposeCategory} from './categories.js';
import {remaining,startTimer,pauseTimer,resumeTimer,addTime,formatTime} from './timer.js';
import {TIERS,COLORS,shuffle,swap,evaluate,totals,outcome} from './core.js';
import {createTable} from './table.js';
const app=document.querySelector('#app');const KEY='rank-party-v2';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,table=null,saved=null,sound=false,audioContext=null,timerInterval=null;
let setup={names:['Player 1','Player 2','Player 3'],selected:CATEGORIES.map(c=>c.id),categoryChoice:'random',drawMode:'category',custom:'',timerSeconds:90};
try{saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version!==2||!Array.isArray(saved.names)||!Array.isArray(saved.history))saved=null;}catch{}
const name=()=>state.names[state.round%state.names.length];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
function ping(hit=true){if(!sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.type='sine';o.frequency.setValueAtTime(hit?660:220,audioContext.currentTime);o.frequency.exponentialRampToValueAtTime(hit?990:165,audioContext.currentTime+.13);g.gain.setValueAtTime(.055,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.23);o.start();o.stop(audioContext.currentTime+.24);}catch{}}
document.querySelector('#rules-button').onclick=()=>document.querySelector('#rules').showModal();document.querySelectorAll('.close,.close-rules').forEach(b=>b.onclick=()=>document.querySelector('#rules').close());document.querySelector('#sound-button').onclick=e=>{sound=!sound;e.currentTarget.textContent=`Sound: ${sound?'on':'off'}`;e.currentTarget.setAttribute('aria-pressed',sound);if(sound)ping();};
function mount(html){clearInterval(timerInterval);timerInterval=null;table?.destroy();table=null;app.innerHTML=html;window.scrollTo({top:0,behavior:'instant'});}
function scene(items,options){table=createTable(document.querySelector('#scene'),items,options);}
function readSetup(){setup.names=[...document.querySelectorAll('.name-input')].map(x=>x.value);setup.selected=[...document.querySelectorAll('input[name="category"]:checked')].map(x=>x.value);setup.drawMode=document.querySelector('#draw-mode').value;setup.timerSeconds=Number(document.querySelector('#timer-duration').value);setup.custom=document.querySelector('#custom').value;}
function selectedPools(){return setup.categoryChoice==='random'?makePools(CATEGORIES.map(c=>c.id)):makePools(setup.selected,customCards(setup.custom));}
function selectionSummary(){const count=poolSize(selectedPools());if(setup.categoryChoice==='random')return 'Random category · 120 cards';return `${setup.selected.length} ${setup.selected.length===1?'category':'categories'} selected · ${count} cards`;}
function renderSetup(){
 mount(`<div class="setup-heading"><div><h1>New game</h1><p>Rank five cards. The others guess your order.</p></div><span class="setup-meta">2–8 players · One device</span></div>${saved?'<div class="resume"><span>You have a saved game.</span><button id="resume">Continue game →</button></div>':''}<form id="setup-form" class="setup-layout"><aside class="setup-players"><div class="section-title"><span>01</span><h2>Players</h2></div><div class="names">${setup.names.map((n,i)=>`<div class="name-row"><span class="seat">${i+1}</span><input class="name-input" aria-label="Player ${i+1} name" maxlength="20" value="${esc(n)}" placeholder="Name" required><button class="remove" type="button" data-remove="${i}" aria-label="Remove player ${i+1}" ${setup.names.length<=2?'disabled':''}>×</button></div>`).join('')}</div><button class="add" type="button" id="add" ${setup.names.length>=8?'disabled':''}>+ Add player</button><label class="field-label" for="timer-duration">Time per turn</label><select id="timer-duration">${[[0,'No timer'],[60,'1 minute'],[90,'90 seconds'],[120,'2 minutes']].map(([v,label])=>`<option value="${v}" ${setup.timerSeconds===v?'selected':''}>${label}</option>`).join('')}</select><p class="field-help">A separate timer for ranking and guessing. You can pause or add time.</p><div class="rules-short"><h3>Scoring</h3><p>Exact match: team +1.<br>Wrong position: game +1.</p><p>Everyone ranks once. The higher total wins.</p></div></aside><section class="category-section"><div class="section-title"><span>02</span><h2>Categories</h2></div><div class="category-intro"><div class="setup-deck" aria-hidden="true"><i>1—5</i><i>1—5</i><i>1—5</i><i>1—5</i></div><h3>A category for every round.</h3><p>Shuffle, draw, and turn it over.<br>You can always choose another category.</p><button type="button" class="secondary" id="category-mode">${setup.categoryChoice==='random'?'Choose categories instead':'Use random draw'}</button></div><div ${setup.categoryChoice==='random'?'hidden':''}><p class="section-description">Select what you want to rank. You can choose more than one.</p><div class="draw-controls"><label for="draw-mode">Draw cards</label><select id="draw-mode"><option value="category" ${setup.drawMode==='category'?'selected':''}>One category per round</option><option value="mixed" ${setup.drawMode==='mixed'?'selected':''}>Mix selected categories</option></select></div><p class="field-help" id="draw-help">${setup.drawMode==='category'?'Selected categories take turns. All five cards in a round share a category.':'Each round draws across your selected categories.'}</p><div class="category-list">${CATEGORIES.map((c,i)=>`<div class="category-row"><label class="category-choice"><input type="checkbox" name="category" id="cat-${c.id}" value="${c.id}" ${setup.selected.includes(c.id)?'checked':''}>${categoryArtMarkup(c.id)}<span class="category-text"><strong>${c.name}</strong><small>${c.description}</small></span></label><details class="card-preview"><summary>${c.cards.length} cards</summary><div class="preview-cards">${c.cards.map(x=>`<span>${esc(x)}</span>`).join('')}</div></details></div>`).join('')}<div class="category-row custom-row"><label class="category-choice"><input type="checkbox" name="category" id="cat-custom" value="custom" ${setup.selected.includes('custom')?'checked':''}><span class="category-number">07</span><span class="category-text"><strong>Custom cards</strong><small>Add your own topics.</small></span></label><div class="custom-editor"><label class="field-label" for="custom">One card per line</label><textarea id="custom" placeholder="Coffee\nRainy days\nBoard games\nCamping\nCilantro" maxlength="4000">${esc(setup.custom)}</textarea><p class="field-help">5–60 different cards, up to 32 characters each.</p></div></div></div></div></section><div class="setup-bottom"><div><strong id="selection-summary">${selectionSummary()}</strong><p>Cards repeat only after the available pool runs out.</p><p class="error" id="error" role="alert"></p></div><button class="primary" type="submit">Start game <span>→</span></button></div></form>`);
 document.querySelector('#category-mode').onclick=()=>{readSetup();setup.categoryChoice=setup.categoryChoice==='random'?'manual':'random';renderSetup();};
 document.querySelector('#add').onclick=()=>{readSetup();let i=1;while(setup.names.includes(`Player ${i}`))i++;setup.names.push(`Player ${i}`);renderSetup();};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{readSetup();setup.names.splice(Number(b.dataset.remove),1);renderSetup();});
 document.querySelectorAll('input[name="category"]').forEach(el=>el.onchange=()=>{readSetup();document.querySelector('#selection-summary').textContent=selectionSummary();});
 document.querySelector('#custom').oninput=()=>{readSetup();document.querySelector('#selection-summary').textContent=selectionSummary();};
 document.querySelector('#draw-mode').onchange=()=>{readSetup();document.querySelector('#draw-help').textContent=setup.drawMode==='category'?'Selected categories take turns. All five cards in a round share a category.':'Each round draws across your selected categories.';};
 document.querySelector('#setup-form').onsubmit=e=>{e.preventDefault();readSetup();const names=setup.names.map(x=>x.trim()),pools=selectedPools(),custom=customCards(setup.custom),error=document.querySelector('#error');if(names.some(x=>!x)||new Set(names.map(x=>x.toLowerCase())).size!==names.length){error.textContent='Enter a different name for each player.';return;}if(!pools.length){error.textContent='Select at least one category.';return;}if(setup.categoryChoice==='manual'&&setup.selected.includes('custom')&&(custom.length<5||custom.length>60||custom.some(x=>x.length>32))){error.textContent='Custom cards need 5–60 different topics, up to 32 characters each.';return;}state={version:2,names,pools,categoryChoice:setup.categoryChoice,drawMode:setup.categoryChoice==='random'?'category':setup.drawMode,categoryQueue:[],timerSeconds:setup.timerSeconds,round:0,history:[],used:[],phase:'handoff-rank',rankConfidence:60,guessConfidence:60};newRound();};
 if(saved)document.querySelector('#resume').onclick=()=>{state=saved;if(['rank','guess'].includes(state.phase)){pauseActiveTimer();state.returnPhase=state.phase;state.phase='shield';}render();};
}
function newRound(){
 state.timer=null;
 if(state.categoryChoice==='random'){state.categoryDraw=proposeCategory(state.pools,state.categoryQueue);state.phase='category';render();return;}
 if(state.pools){const draw=drawRound({pools:state.pools,mode:state.drawMode,used:state.used,categoryQueue:state.categoryQueue});state.cards=draw.cards;state.used=draw.used;state.categoryQueue=draw.categoryQueue;state.roundCategory=draw.label;state.cardCategories=draw.cardCategories;}
 else {let available=state.deck.filter(x=>!state.used.includes(x));if(available.length<5){available=[...state.deck];state.used=[];}state.cards=shuffle(available).slice(0,5);state.used.push(...state.cards);state.roundCategory=state.deckName||'Cards';}
 state.secret=[...state.cards];state.guess=[...state.cards];state.rankConfidence=60;state.guessConfidence=60;state.revealed=0;state.current=null;state.phase='handoff-rank';render();
}
function top(){let t=totals(state.history);if(state.phase==='reveal'&&state.current){const hits=state.current.matches.slice(0,state.revealed).filter(Boolean).length;t.team+=hits;t.game+=state.revealed-hits;}return `<div class="round-header"><div class="round-category">${esc(state.phase==='category'?'Category draw':state.roundCategory||state.deckName||'Cards')}</div><div class="game-top"><span class="round-label">${state.round>=state.names.length?'OVERTIME · ':''}ROUND ${String(state.round+1).padStart(2,'0')} <span> / ${String(state.names.length).padStart(2,'0')}</span></span><div class="scoreboard" aria-label="Current score"><span class="team">Team <b>${t.team}</b></span><i>VS</i><span>Game <b>${t.game}</b></span></div><button class="quit" id="quit">Leave game</button></div></div>`;}
function bindQuit(){document.querySelector('#quit')?.addEventListener('click',()=>{pauseActiveTimer();bindTimer();const d=document.createElement('dialog');d.innerHTML='<h2>Leave this game?</h2><p>Your progress is saved on this device.</p><div class="confirm-buttons"><button class="secondary" id="stay">Keep playing</button><button class="primary" id="leave">Game setup</button></div>';document.body.append(d);d.showModal();d.querySelector('#stay').onclick=()=>{d.close();d.remove();};d.querySelector('#leave').onclick=()=>{save();saved=state;state=null;d.close();d.remove();renderSetup();};d.addEventListener('cancel',()=>d.remove());});}
function phases(active){return `<div class="phase-steps"><span class="${active===0?'active':''}">01 Secret ranking</span><span class="${active===1?'active':''}">02 Team guess</span><span class="${active===2?'active':''}">03 The reveal</span></div>`;}
function render(){save();if(state.phase==='category')renderCategoryDraw();else if(state.phase.startsWith('handoff')||state.phase==='shield')renderHandoff();else if(state.phase==='rank'||state.phase==='guess')renderOrder();else if(state.phase==='reveal')renderReveal();else renderResult();bindQuit();}

function renderCategoryDraw(){
 const proposal=state.categoryDraw,category=state.pools.find(p=>p.id===proposal.id);
 mount(top()+`<section class="category-draw"><span class="eyebrow">${esc(name())}’S ROUND</span><h1 id="draw-title">${proposal.revealed?'This round’s category':'Drawing a category…'}</h1><div id="category-stage" class="category-stage" aria-hidden="true"></div><div class="draw-result" aria-live="polite"><h2 id="category-name">${proposal.revealed?esc(category.name):'Shuffling the deck'}</h2><p id="category-description">${proposal.revealed?'Five cards from this category.':'Cut. Fan. Draw.'}</p></div><div class="category-actions"><button class="primary" id="use-category" ${proposal.revealed?'':'disabled'}>Use this category →</button><button class="secondary" id="choose-category">Choose category</button><button class="quiet" id="skip-draw" ${proposal.revealed?'hidden':''}>Skip animation</button></div></section>`);
 table=createCategoryDraw(document.querySelector('#category-stage'),category,{revealed:proposal.revealed,onComplete:()=>{if(state?.categoryDraw!==proposal)return;proposal.revealed=true;save();document.querySelector('#draw-title').textContent='This round’s category';document.querySelector('#category-name').textContent=category.name;document.querySelector('#category-description').textContent='Five cards from this category.';document.querySelector('#use-category').disabled=false;document.querySelector('#skip-draw').hidden=true;}});
 document.querySelector('#skip-draw').onclick=()=>table.skip();
 document.querySelector('#use-category').onclick=()=>{const draw=drawRound({pools:[category],used:state.used});state.cards=draw.cards;state.used=draw.used;state.categoryQueue=proposal.after;state.roundCategory=draw.label;state.cardCategories=draw.cardCategories;state.secret=[...draw.cards];state.guess=[...draw.cards];state.rankConfidence=60;state.guessConfidence=60;state.revealed=0;state.current=null;state.phase='handoff-rank';render();};
 document.querySelector('#choose-category').onclick=()=>{table.skip();const d=document.createElement('dialog');d.setAttribute('aria-label','Choose category');d.innerHTML=`<button class="close" aria-label="Close">×</button><h2>Choose category</h2><div class="category-picker">${state.pools.map(p=>`<button class="secondary" data-category="${esc(p.id)}" ${p.id===category.id?'aria-pressed="true"':''}>${categoryArtMarkup(p.id)}<strong>${esc(p.name)}</strong><small>${p.cards.length} cards</small></button>`).join('')}</div>`;document.body.append(d);d.showModal();d.querySelector('.close').onclick=()=>{d.close();d.remove();};d.addEventListener('cancel',()=>d.remove());d.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.categoryDraw={...proposeCategory(state.pools,proposal.before,b.dataset.category),revealed:true};d.close();d.remove();render();});};
}

function renderHandoff(){const rank=state.phase==='handoff-rank'||(state.phase==='shield'&&state.returnPhase==='rank');const resume=state.phase==='shield';mount(top()+`<section class="handoff"><div class="back-card">${rank?'B':'?'}</div><span class="eyebrow">${resume?'RESUME GAME':'NEXT PLAYER'}</span><h2>${rank?`Pass the device to<br>${esc(name())}`:'Pass to the other players'}</h2><p>${rank?'Everyone else, look away.<br>Rank the cards from favorite to least favorite.':`${esc(name())} has locked in a ranking.<br>Pass the device to the others and let them discuss.`}</p><button class="primary" id="ready">${rank?`Start ranking as ${esc(name())}`:'Start guessing'} <span>→</span></button><p class="micro">${rank?'Only the ranker should see the next screen.':'The ranker should not help with the guess.'}</p></section>`);document.querySelector('#ready').onclick=()=>{state.phase=rank?'rank':'guess';if(resume&&state.timer&&state.timer.remaining>0)resumeTimer(state.timer);delete state.returnPhase;render();};}
function confidence(rank){const key=rank?'rankConfidence':'guessConfidence';return `<div><label class="confidence-label" for="confidence"><span>${rank?'How many do you think they’ll match?':'How many do you think you’ll match?'}</span><output id="confidence-output" for="confidence">${state[key]}%</output></label><input id="confidence" type="range" min="0" max="100" step="10" value="${state[key]}"><div class="range-caption"><span>0% · Not a single match</span><span>100% · All five</span></div></div>`;}
function rankCells(order){return order.map((item,i)=>`<div class="rank-cell" style="--tier:${COLORS[i]}"><div class="rank-tier"><b>${i+1}</b>${TIERS[i]}</div><span class="rank-name">${esc(item)}${state.drawMode==='mixed'&&state.cardCategories?.[item]?`<small class="card-category">${esc(state.cardCategories[item])}</small>`:''}</span><div class="reorder"><button data-from="${i}" data-to="${i-1}" aria-label="${esc(item)} move up" ${i===0?'disabled':''}>←</button><button data-from="${i}" data-to="${i+1}" aria-label="${esc(item)} move down" ${i===4?'disabled':''}>→</button></div></div>`).join('');}
function renderOrder(){const rank=state.phase==='rank',key=rank?'secret':'guess';mount(top()+phases(rank?0:1)+`<div class="play-heading"><div><h2>${rank?`${esc(name())}: rank the cards`:`Guess ${esc(name())}’s ranking`}</h2><p>${rank?'Order the cards from your favorite to your least favorite.':'Discuss with the other players and submit one shared order.'}<br>Use the arrows to swap cards. 1 = favorite, 5 = least favorite.</p></div><span class="pill">${rank?'FOR YOUR EYES ONLY':'ONE SHARED TEAM GUESS'}</span></div>${timerMarkup()}<div id="scene" class="scene play-scene" aria-hidden="true"></div><div class="rank-grid" id="rank-grid">${rankCells(state[key])}</div><div class="bottom-panel">${confidence(rank)}<div><button class="primary" id="lock">${rank?'Submit ranking':'Submit guess'} <span>→</span></button><p class="micro">You cannot edit after submitting.</p></div></div>`);scene(state[key]);bindMove(key);bindTimer();document.querySelector('#confidence').oninput=e=>{state[rank?'rankConfidence':'guessConfidence']=Number(e.target.value);document.querySelector('#confidence-output').textContent=e.target.value+'%';save();};document.querySelector('#lock').onclick=()=>{pauseActiveTimer();if(rank){state.phase='handoff-guess';state.guess=[...state.cards];}else{state.current=evaluate(state.secret,state.guess,state.rankConfidence,state.guessConfidence);state.phase='reveal';state.revealed=0;}render();};}
function bindMove(key){document.querySelectorAll('[data-from]').forEach(b=>b.onclick=()=>{const from=Number(b.dataset.from),to=Number(b.dataset.to);state[key]=swap(state[key],from,to);save();table.update(state[key]);document.querySelector('#rank-grid').innerHTML=rankCells(state[key]);bindMove(key);const focus=document.querySelector(`[data-from="${to}"][data-to="${to+(to>from?1:-1)}"]`);(focus&&!focus.disabled?focus:document.querySelector(`[data-from="${to}"]:not(:disabled)`))?.focus({preventScroll:true});});}
function revealCells(){return state.guess.map((item,i)=>`<div class="rank-cell revealed" style="--tier:${COLORS[i]}"><div class="rank-tier"><b>${i+1}</b>${TIERS[i]}</div>${i<state.revealed?`<span class="rank-name">${esc(item)}${state.drawMode==='mixed'&&state.cardCategories?.[item]?`<small class="card-category">${esc(state.cardCategories[item])}</small>`:''}</span><div class="answer-line">Their #${i+1}: ${esc(state.secret[i])}</div><div class="${state.current.matches[i]?'hit':'miss'}">${state.current.matches[i]?'Match · Team +1':'Miss · Game +1'}</div>`:'<div class="unknown">?</div>'}</div>`).join('');}
function renderReveal(){mount(top()+phases(2)+`<div class="play-heading"><div><h2>Reveal the ranking</h2><p>Compare each position with your team’s guess.</p></div><span class="pill">${esc(name())}’s secret ranking</span></div><div id="scene" class="scene play-scene" aria-hidden="true"></div><div class="rank-grid" id="reveal-grid" aria-live="polite">${revealCells()}</div><div class="bottom-panel"><div class="reveal-summary" id="reveal-status">${revealStatus()}</div><div><button class="primary" id="flip">${state.revealed<5?`Reveal card ${state.revealed+1}`:'Round results'} <span>↗</span></button><p class="micro">One point per card · Only exact positions count</p></div></div>`);scene(state.secret,{concealed:true});table.update(state.secret,{revealed:state.revealed});document.querySelector('#flip').onclick=()=>{if(state.revealed<5){state.revealed++;save();table.update(state.secret,{revealed:state.revealed,flip:true});document.querySelector('#reveal-grid').innerHTML=revealCells();document.querySelector('#reveal-status').textContent=revealStatus();const oldTop=document.querySelector('.round-header');oldTop.outerHTML=top();bindQuit();document.querySelector('#flip').innerHTML=`${state.revealed<5?`Reveal card ${state.revealed+1}`:'Round results'} <span>↗</span>`;ping(state.current.matches[state.revealed-1]);}else{state.history.push({...state.current,ranker:name(),ranking:[...state.secret],rankConfidence:state.rankConfidence,guessConfidence:state.guessConfidence});state.phase='result';render();}};}
function revealStatus(){const hits=state.current.matches.slice(0,state.revealed).filter(Boolean).length;return state.revealed?`Revealed ${state.revealed} / 5 · Matched ${hits}${state.revealed===5?'.':''}`:'Reveal the first card to start scoring.';}
function renderResult(){const end=outcome(state.history,state.names.length),last=state.history.at(-1),done=['win','lose'].includes(end);const index=done?Math.round(state.history.reduce((s,r)=>s+r.index,0)/state.history.length):last.index;const acc=done?state.history.reduce((s,r)=>s+r.accuracy,0)/state.history.length:last.accuracy;const calibration=done?state.history.reduce((s,r)=>s+r.calibration,0)/state.history.length:last.calibration;mount(top()+`<div class="result-layout"><section><span class="eyebrow">${done?'FINAL RESULT':'ROUND RESULT'}</span><h2 class="result-title">${end==='win'?'Your team wins':end==='lose'?'The game wins':end==='overtime'?'Tie. Play another round.':`Matched ${last.hits} ${last.hits===1?'card':'cards'}.`}</h2><p class="result-copy">${done?'All players share this result.':`${esc(last.ranker)}’s round is complete. Team +${last.hits}, Game +${last.misses}.<br>The next player will rank a new set of cards.`}</p><div class="round-history">${state.history.map((r,i)=>`<div class="round-record"><div class="history-row"><span>${String(i+1).padStart(2,'0')} / ${esc(r.ranker)}</span><b>Matched ${r.hits} / 5</b><span>Connection ${r.index}</span></div>${r.note?`<div class="saved-note"><span>${esc(r.note.card||'Overall ranking')}</span><p>${esc(r.note.text)}</p></div>`:''}<button class="quiet note-trigger" data-note="${i}">${r.note?'Edit note':'Add a note'}</button>${i===state.history.length-1?'<span class="note-optional">Optional · For the ranker · No effect on score</span>':''}</div>`).join('')}</div><div class="result-actions">${done?'<button class="primary" id="again">Play again</button><button class="secondary" id="home">New setup</button>':`<button class="primary" id="next">${end==='overtime'?'Play overtime':`Up next: ${esc(state.names[(state.round+1)%state.names.length])}`} <span>→</span></button>`}</div></section><aside class="paper"><span class="eyebrow">${done?'TEAM CONNECTION':'ROUND CONNECTION'}</span><h2>${done?'Overall':'Round'} connection score</h2><div class="index-number">${index}<small> / 100</small></div><p class="intro">Based on matches and confidence predictions.</p><div class="metric-row"><span>Matches · 40% weight</span><strong>${Math.round(acc*100)}%</strong></div><div class="metric-row"><span>Confidence · 60% weight</span><strong>${Math.round(calibration*100)}%</strong></div>${!done?`<div class="metric-row"><span>Ranker / team prediction</span><strong>${last.rankConfidence}% / ${last.guessConfidence}%</strong></div>`:''}<p class="micro">${done?'Average of all round scores':'40 × match rate + 60 × confidence accuracy'}<br>Connection scores are for reflection, not victory points.</p></aside></div>`);bindNotes();if(done){document.querySelector('#again').onclick=()=>{state.history=[];state.round=0;state.used=[];state.categoryQueue=[];newRound();};document.querySelector('#home').onclick=()=>{saved=null;state=null;try{localStorage.removeItem(KEY);}catch{}renderSetup();};}else document.querySelector('#next').onclick=()=>{state.round++;newRound();};}

function bindNotes(){
 document.querySelectorAll('[data-note]').forEach(button=>button.onclick=()=>{
  const round=state.history[Number(button.dataset.note)],d=document.createElement('dialog');
  d.className='note-dialog';d.setAttribute('aria-labelledby','note-heading');
  d.innerHTML=`<h2 id="note-heading">${esc(round.ranker)}’s note</h2><p>Anything you’d like to explain about your ranking?</p><form id="note-form"><label class="field-label" for="note-card">About</label><select id="note-card"><option value="">Overall ranking</option>${(round.ranking||[]).map((card,i)=>`<option value="${esc(card)}" ${round.note?.card===card?'selected':''}>${i+1}. ${esc(card)}</option>`).join('')}</select><label class="field-label" for="note-text">Your note</label><textarea id="note-text" maxlength="200" placeholder="One sentence is enough." rows="3">${esc(round.note?.text||'')}</textarea><p class="field-help">Optional. Saved on this browser only, visible to people using this device. Not sent to Sammy.</p><p class="field-help" id="note-count">${(round.note?.text||'').length} / 200</p><div class="note-buttons"><button type="button" class="secondary" id="note-cancel">Cancel</button><button type="submit" class="primary" id="note-save">Save note</button>${round.note?'<button type="button" class="quiet" id="note-remove">Remove note</button>':''}</div></form>`;
  document.body.append(d);d.showModal();
  const input=d.querySelector('#note-text'),submit=d.querySelector('#note-save');
  const update=()=>{submit.disabled=!input.value.trim();d.querySelector('#note-count').textContent=`${input.value.length} / 200`;};update();input.oninput=update;
  function close(){d.close();d.remove();button.focus();}
  d.querySelector('#note-cancel').onclick=close;d.addEventListener('cancel',e=>{e.preventDefault();close();});
  d.querySelector('#note-form').onsubmit=e=>{e.preventDefault();const text=input.value.trim();if(!text)return;round.note={text:text.slice(0,200),card:d.querySelector('#note-card').value};close();render();};
  d.querySelector('#note-remove')?.addEventListener('click',()=>{delete round.note;close();render();});
 });
}

document.addEventListener('visibilitychange',()=>{if(document.hidden&&state&&['rank','guess'].includes(state.phase)){pauseActiveTimer();state.returnPhase=state.phase;state.phase='shield';render();}});
document.querySelector('.brand').onclick=e=>{e.preventDefault();if(state){pauseActiveTimer();save();saved=state;state=null;}renderSetup();};
function timerMarkup(){return (state.timerSeconds??90)>0?`<section class="turn-timer" aria-label="Turn timer"><div class="timer-clock"><span class="timer-label">TURN TIMER</span><output id="timer-clock" aria-label="Time remaining">${formatTime((state.timerSeconds??90)*1000)}</output></div><p id="timer-status" role="status">Time remaining for this turn.</p><div class="timer-actions"><button id="timer-pause" class="secondary">Pause</button><button id="timer-add" class="secondary">+30 sec</button></div></section>`:'';}
function pauseActiveTimer(){if(state?.timer){pauseTimer(state.timer);save();}clearInterval(timerInterval);timerInterval=null;}
function bindTimer(){
 if(!document.querySelector('#timer-clock'))return;
 const id=`${state.round}:${state.phase}`;
 if(!state.timer||state.timer.id!==id){state.timer=startTimer(state.timerSeconds??90,id);save();}
 const clock=document.querySelector('#timer-clock'),status=document.querySelector('#timer-status'),button=document.querySelector('#timer-pause'),bar=document.querySelector('.turn-timer');
 function update(){const t=state.timer,ms=remaining(t);clock.textContent=formatTime(ms);bar.classList.toggle('timer-low',ms<=10000);button.textContent=t.running?'Pause':'Resume';button.disabled=ms===0;const message=ms===0?'Time’s up. Lock it in, or add more time.':t.running?'Time remaining for this turn.':'Timer paused.';if(status.textContent!==message)status.textContent=message;if(ms===0&&!t.alerted){pauseTimer(t);t.alerted=true;save();ping(false);}}
 button.onclick=()=>{if(state.timer.running)pauseTimer(state.timer);else resumeTimer(state.timer);save();update();};
 document.querySelector('#timer-add').onclick=()=>{addTime(state.timer,30);save();update();};
 update();timerInterval=setInterval(update,250);
}
window.addEventListener('pagehide',pauseActiveTimer);
renderSetup();
